  1→import { app } from "../../../scripts/app.js";
  2→import { renderText, createTypingIndicator, createPanel } from "./chat.js";
  3→
  4→/* ── SUPER DUPER Sidebar ─────────────────────────────────────────────
  5→ *  Registers a sidebar tab in ComfyUI's extension manager.
  6→ *  Chat interface with WebSocket connection to agent brain.
  7→ * ──────────────────────────────────────────────────────────────────── */
  8→
  9→const SIDEBAR_ID = "superduper";
 10→const SIDEBAR_TITLE = "SUPER DUPER";
 11→
 12→/* ── Load stylesheet ──────────────────────────────────────────────── */
 13→
 14→const cssLink = document.createElement("link");
 15→cssLink.rel = "stylesheet";
 16→cssLink.href = new URL("../css/superduper.css", import.meta.url).href;
 17→document.head.appendChild(cssLink);
 18→
 19→/* ── Message rendering ────────────────────────────────────────────── */
 20→
 21→function createMessageEl(role, text) {
 22→  const msg = document.createElement("div");
 23→  msg.className = `sd-message sd-message--${role}`;
 24→
 25→  if (role !== "system") {
 26→    const label = document.createElement("span");
 27→    label.className = "sd-message__label";
 28→    label.textContent = role === "user" ? "You" : "Agent";
 29→    msg.appendChild(label);
 30→  }
 31→
 32→  const body = document.createElement("div");
 33→  body.className = "sd-message__body";
 34→
 35→  if (role === "agent") {
 36→    // Rich text rendering for agent messages
 37→    body.classList.add("sd-text-body");
 38→    body.appendChild(renderText(text));
 39→  } else {
 40→    // Plain text for user and system messages
 41→    body.textContent = text;
 42→  }
 43→
 44→  msg.appendChild(body);
 45→  return msg;
 46→}
 47→
 48→/* ── WebSocket connection ─────────────────────────────────────────── */
 49→
 50→class AgentConnection {
 51→  constructor(onMessage, onStatus) {
 52→    this.ws = null;
 53→    this.onMessage = onMessage;   // (event) => void
 54→    this.onStatus = onStatus;     // (status) => void
 55→    this.reconnectDelay = 1000;
 56→    this.maxReconnectDelay = 15000;
 57→    this.currentDelay = this.reconnectDelay;
 58→    this._closed = false;
 59→  }
 60→
 61→  connect() {
 62→    const proto = location.protocol === "https:" ? "wss:" : "ws:";
 63→    const url = `${proto}//${location.host}/superduper/ws`;
 64→
 65→    this.onStatus("connecting");
 66→    this.ws = new WebSocket(url);
 67→
 68→    this.ws.onopen = () => {
 69→      this.currentDelay = this.reconnectDelay;
 70→      this.onStatus("connected");
 71→    };
 72→
 73→    this.ws.onmessage = (evt) => {
 74→      try {
 75→        const data = JSON.parse(evt.data);
 76→        this.onMessage(data);
 77→      } catch (e) {
 78→        console.error("[SUPER DUPER] Bad message:", evt.data);
 79→      }
 80→    };
 81→
 82→    this.ws.onclose = () => {
 83→      this.onStatus("disconnected");
 84→      if (!this._closed) {
 85→        setTimeout(() => this.connect(), this.currentDelay);
 86→        this.currentDelay = Math.min(this.currentDelay * 1.5, this.maxReconnectDelay);
 87→      }
 88→    };
 89→
 90→    this.ws.onerror = (err) => {
 91→      console.error("[SUPER DUPER] WebSocket error:", err);
 92→    };
 93→  }
 94→
 95→  send(type, payload) {
 96→    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
 97→      this.ws.send(JSON.stringify({ type, ...payload }));
 98→      return true;
 99→    }
100→    return false;
101→  }
102→
103→  close() {
104→    this._closed = true;
105→    if (this.ws) this.ws.close();
106→  }
107→}
108→
109→/* ── Build the sidebar DOM ────────────────────────────────────────── */
110→
111→function buildSidebar(el) {
112→  el.style.height = "100%";
113→  el.style.display = "flex";
114→  el.style.flexDirection = "column";
115→
116→  el.innerHTML = `
117→    <div class="sd-header">
118→      <span class="sd-header__title">${SIDEBAR_TITLE}</span>
119→      <span class="sd-header__status" id="sd-status"></span>
120→    </div>
121→    <div class="sd-stage-bar" id="sd-stage" style="display:none">
122→      <span class="sd-stage__label" id="sd-stage-label"></span>
123→      <span class="sd-stage__detail" id="sd-stage-detail"></span>
124→    </div>
125→    <div class="sd-messages" id="sd-messages">
126→      <div class="sd-message sd-message--system">
127→        <span class="sd-message__body">Ready. Type below.</span>
128→      </div>
129→    </div>
130→    <div class="sd-input-bar">
131→      <input
132→        type="text"
133→        id="sd-input"
134→        class="sd-input"
135→        placeholder="Ask me anything about your workflow..."
136→        autocomplete="off"
137→      />
138→      <button id="sd-send" class="sd-send-btn">Send</button>
139→    </div>
140→  `;
141→
142→  const messagesEl = el.querySelector("#sd-messages");
143→  const inputEl = el.querySelector("#sd-input");
144→  const sendBtn = el.querySelector("#sd-send");
145→  const statusEl = el.querySelector("#sd-status");
146→  const stageBar = el.querySelector("#sd-stage");
147→  const stageLabel = el.querySelector("#sd-stage-label");
148→  const stageDetail = el.querySelector("#sd-stage-detail");
149→
150→  let busy = false;
151→  let streamingEl = null;     // element receiving streamed text deltas
152→  let streamAccum = "";       // accumulated text during streaming
153→  let typingIndicator = null; // typing dots shown during stream
154→
155→  function scrollToBottom() {
156→    messagesEl.scrollTop = messagesEl.scrollHeight;
157→  }
158→
159→  function setStage(stage, detail) {
160→    if (stage === "DONE" || !stage) {
161→      stageBar.style.display = "none";
162→      return;
163→    }
164→    stageBar.style.display = "flex";
165→    stageLabel.textContent = stage;
166→    stageDetail.textContent = detail || "";
167→  }
168→
169→  function setBusy(state) {
170→    busy = state;
171→    sendBtn.disabled = state;
172→    inputEl.disabled = state;
173→    sendBtn.textContent = state ? "..." : "Send";
174→  }
175→
176→  /* ── WebSocket message handler ────────────────────────────────── */
177→
178→  function handleAgentMessage(data) {
179→    switch (data.type) {
180→      case "connected":
181→        break;
182→
183→      case "text_delta":
184→        // Streaming: show typing indicator, accumulate text
185→        if (!streamingEl) {
186→          streamingEl = document.createElement("div");
187→          streamingEl.className = "sd-message sd-message--agent";
188→
189→          const label = document.createElement("span");
190→          label.className = "sd-message__label";
191→          label.textContent = "Agent";
192→          streamingEl.appendChild(label);
193→
194→          const body = document.createElement("div");
195→          body.className = "sd-message__body sd-text-body";
196→          streamingEl.appendChild(body);
197→
198→          messagesEl.appendChild(streamingEl);
199→          streamAccum = "";
200→        }
201→
202→        streamAccum += data.text;
203→
204→        // Show typing indicator during streaming
205→        const streamBody = streamingEl.querySelector(".sd-message__body");
206→        if (!typingIndicator) {
207→          typingIndicator = createTypingIndicator();
208→          streamBody.appendChild(typingIndicator);
209→        }
210→
211→        scrollToBottom();
212→        break;
213→
214→      case "message": {
215→        // Full message — render with rich text, replacing streaming element
216→        const finalText = data.content || streamAccum;
217→
218→        if (streamingEl) {
219→          // Replace streaming content with final rendered text
220→          const body = streamingEl.querySelector(".sd-message__body");
221→          body.textContent = ""; // clear typing indicator
222→          body.classList.add("sd-text-body");
223→          body.appendChild(renderText(finalText));
224→          streamingEl = null;
225→          streamAccum = "";
226→          typingIndicator = null;
227→        } else {
228→          messagesEl.appendChild(createMessageEl("agent", finalText));
229→        }
230→        scrollToBottom();
231→        break;
232→      }
233→
234→      case "panel": {
235→        // Structured panel from tool result
236→        const panelEl = createPanel(data.panel);
237→        if (panelEl) {
238→          // Wrap in a message container for consistent spacing
239→          const wrapper = document.createElement("div");
240→          wrapper.className = "sd-message sd-message--agent";
241→          wrapper.style.padding = "0";
242→          wrapper.style.background = "none";
243→          wrapper.appendChild(panelEl);
244→          messagesEl.appendChild(wrapper);
245→          scrollToBottom();
246→        }
247→        break;
248→      }
249→
250→      case "stage":
251→        setStage(data.stage, data.detail);
252→        if (data.stage === "DONE") {
253→          // Clean up streaming state
254→          if (streamingEl && streamAccum) {
255→            const body = streamingEl.querySelector(".sd-message__body");
256→            body.textContent = "";
257→            body.classList.add("sd-text-body");
258→            body.appendChild(renderText(streamAccum));
259→          }
260→          streamingEl = null;
261→          streamAccum = "";
262→          typingIndicator = null;
263→          setBusy(false);
264→        }
265→        break;
266→
267→      case "error":
268→        setStage(null);
269→        messagesEl.appendChild(createMessageEl("system", data.message));
270→        streamingEl = null;
271→        streamAccum = "";
272→        typingIndicator = null;
273→        setBusy(false);
274→        scrollToBottom();
275→        break;
276→
277→      default:
278→        console.log("[SUPER DUPER] Unknown event:", data);
279→    }
280→  }
281→
282→  function handleStatus(status) {
283→    statusEl.textContent = status === "connected" ? "" : status;
284→    statusEl.className = `sd-header__status sd-header__status--${status}`;
285→  }
286→
287→  /* ── Connect ──────────────────────────────────────────────────── */
288→
289→  const conn = new AgentConnection(handleAgentMessage, handleStatus);
290→  conn.connect();
291→
292→  /* ── Send message ─────────────────────────────────────────────── */
293→
294→  async function sendMessage() {
295→    const text = inputEl.value.trim();
296→    if (!text || busy) return;
297→
298→    // Show user message
299→    messagesEl.appendChild(createMessageEl("user", text));
300→    inputEl.value = "";
301→    scrollToBottom();
302→
303→    // Capture current workflow from ComfyUI canvas
304→    let workflow = null;
305→    try {
306→      const result = await app.graphToPrompt();
307→      if (result && result.output) {
308→        workflow = result.output;
309→      }
310→    } catch (e) {
311→      console.warn("[SUPER DUPER] Could not capture workflow:", e);
312→    }
313→
314→    // Send to agent via WebSocket (include workflow if captured)
315→    const payload = { content: text };
316→    if (workflow) {
317→      payload.workflow = workflow;
318→    }
319→    const sent = conn.send("chat", payload);
320→    if (!sent) {
321→      messagesEl.appendChild(
322→        createMessageEl("system", "Not connected. Reconnecting...")
323→      );
324→      scrollToBottom();
325→      return;
326→    }
327→
328→    setBusy(true);
329→  }
330→
331→  sendBtn.addEventListener("click", sendMessage);
332→  inputEl.addEventListener("keydown", (e) => {
333→    if (e.key === "Enter" && !e.shiftKey) {
334→      e.preventDefault();
335→      sendMessage();
336→    }
337→  });
338→
339→  setTimeout(() => inputEl.focus(), 100);
340→}
341→
342→/* ── Register with ComfyUI ────────────────────────────────────────── */
343→
344→app.extensionManager.registerSidebarTab({
345→  id: SIDEBAR_ID,
346→  icon: "pi pi-bolt",
347→  title: SIDEBAR_TITLE,
348→  tooltip: "SUPER DUPER AI Co-pilot",
349→  type: "custom",
350→  render(el) {
351→    buildSidebar(el);
352→  },
353→});
